-- ============================================================================
-- The core customer mails exist in Swedish (2026-11-19).
--
-- Read on a live instance whose site language is Swedish: the invoice, the
-- invoice reminder, the quote, the quote reminder, the agreement, its reminder
-- and the booking confirmation existed in English only. The template ladder
-- (resolve_email_template: the recipient's language, then the site's, then ANY
-- active version) then lands on English — a Swedish business sent its Swedish
-- customers "Please find your invoice attached".
--
-- The later mails (booking reminder, receipt, return, webinar, newsletter,
-- 20261026090000 onward) were seeded in en AND sv; these eight predate that.
-- Seeded explicitly as 'sv', and only where (name, 'sv') is missing: an
-- instance that wrote its own Swedish version keeps it. The English rows are
-- not touched. Nothing is sent.
-- ============================================================================

INSERT INTO public.email_templates (name, locale, subject, html, category, variables, active)
SELECT 'booking_confirmation', 'sv', $subj$Bokningsbekräftelse — {{date}}$subj$, $tpl$<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Bokningsbekräftelse</title></head><body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;"><h1 style="font-size: 22px; margin: 0 0 16px;">Bokningsbekräftelse</h1><p>Hej {{customer_name}},</p><p>Tack för din bokning. Här är uppgifterna:</p><div style="background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; margin: 20px 0;"><p style="margin:4px 0;"><strong>Tjänst:</strong> {{service_name}}</p><p style="margin:4px 0;"><strong>Datum:</strong> {{date}}</p><p style="margin:4px 0;"><strong>Tid:</strong> {{start_time}}–{{end_time}}</p></div>{{#notes}}<div style="background:#f3f4f6;border-radius:8px;padding:12px 16px;margin:16px 0;"><p style="margin:0;"><strong>Din anteckning:</strong> {{notes}}</p></div>{{/notes}}<p>Om något ändras, svara bara på det här mejlet.</p><p style="color:#6b7280; font-size: 13px; margin-top: 28px;">{{site_name}}</p></body></html>$tpl$, 'transactional', $var$["customer_name", "service_name", "date", "start_time", "end_time", "site_name", "notes"]$var$::jsonb, true
WHERE NOT EXISTS (SELECT 1 FROM public.email_templates WHERE name = 'booking_confirmation' AND locale = 'sv');

INSERT INTO public.email_templates (name, locale, subject, html, category, variables, active)
SELECT 'quote_email', 'sv', $subj$Offert {{quote_number}} från {{site_name}}$subj$, $tpl$<h1 style="margin:0 0 8px;font-size:20px">Din offert {{quote_number}}</h1><p style="margin:0 0 16px;color:#4b5563">Tack för ditt intresse. Här är din offert.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px;margin:16px 0"><div style="display:flex;justify-content:space-between;margin-bottom:6px"><span style="color:#6b7280">Offert</span><strong>{{quote_number}}</strong></div><div style="margin-bottom:6px">{{quote_title}}</div><table style="width:100%;border-collapse:collapse;margin:12px 0 4px"><thead><tr><th style="text-align:left;font-size:11px;text-transform:uppercase;color:#6b7280;padding-bottom:6px;border-bottom:1px solid #e6e8ec">Artikel</th><th style="text-align:right;font-size:11px;text-transform:uppercase;color:#6b7280;padding-bottom:6px;border-bottom:1px solid #e6e8ec">Belopp</th></tr></thead><tbody>{{items_rows}}</tbody></table><div style="display:flex;justify-content:space-between;margin-top:8px;font-size:13px"><span style="color:#6b7280">Delsumma</span><span style="font-family:ui-monospace,monospace">{{subtotal}}</span></div><div style="display:flex;justify-content:space-between;font-size:13px"><span style="color:#6b7280">Moms</span><span style="font-family:ui-monospace,monospace">{{tax}}</span></div><div style="display:flex;justify-content:space-between;margin-top:6px;border-top:1px solid #e6e8ec;padding-top:6px"><strong>Totalt</strong><strong style="font-family:ui-monospace,monospace">{{total}}</strong></div><div style="display:flex;justify-content:space-between;margin-top:8px;font-size:12px;color:#6b7280"><span>Giltig till</span><span>{{valid_until}}</span></div></div><div style="text-align:center;margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;background:#111;color:#fff;text-decoration:none;padding:12px 24px;border-radius:8px;font-weight:600">Öppna offerten</a></div><p style="margin:16px 0 0;font-size:12px;color:#6b7280;word-break:break-all">Eller kopiera länken:<br/>{{cta_url}}</p>$tpl$, 'sales', $var$["quote_number", "quote_title", "site_name", "items_rows", "subtotal", "tax", "total", "valid_until", "cta_url", "custom_block"]$var$::jsonb, true
WHERE NOT EXISTS (SELECT 1 FROM public.email_templates WHERE name = 'quote_email' AND locale = 'sv');

