<p style="margin:16px 0 0;font-size:12px;color:#6b7280;word-break:break-all">Eller kopiera länken:<br/>{{cta_url}}</p>$tpl$, 'sales', $var$["quote_number", "quote_title", "site_name", "items_rows", "subtotal", "tax", "total", "valid_until", "cta_url", "custom_block"]$var$::jsonb, true
