SELECT 'invoice_email', 'sv', $subj$Faktura {{invoice_number}} från {{site_name}}$subj$, $tpl$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 8px;font-size:20px">Faktura {{invoice_number}}</h1><p style="margin:0 0 16px;color:#4b5563">Din faktura är bifogad. Du kan också se och betala den på nätet.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px;margin:16px 0"><div style="display:flex;justify-content:space-between;margin-bottom:6px"><span style="color:#6b7280">Faktura</span><strong>{{invoice_number}}</strong></div>{{#items_rows}}<table style="width:100%;border-collapse:collapse;margin:12px 0 4px"><thead><tr><th style="text-align:left;font-size:11px;text-transform:uppercase;color:#6b7280;padding-bottom:6px;border-bottom:1px solid #e6e8ec">Artikel</th><th style="text-align:right;font-size:11px;text-transform:uppercase;color:#6b7280;padding-bottom:6px;border-bottom:1px solid #e6e8ec">Belopp</th></tr></thead><tbody>{{items_rows}}</tbody></table>{{/items_rows}}<div style="display:flex;justify-content:space-between;margin-top:8px;font-size:13px"><span style="color:#6b7280">Delsumma</span><span style="font-family:ui-monospace,monospace">{{subtotal}}</span></div><div style="display:flex;justify-content:space-between;font-size:13px"><span style="color:#6b7280">Moms</span><span style="font-family:ui-monospace,monospace">{{tax}}</span></div><div style="display:flex;justify-content:space-between;margin-top:6px;border-top:1px solid #e6e8ec;padding-top:6px"><strong>Totalt</strong><strong style="font-family:ui-monospace,monospace">{{total}}</strong></div>{{#due_date}}<div style="display:flex;justify-content:space-between;margin-top:8px;font-size:12px;color:#6b7280"><span>Förfaller</span><span>{{due_date}}</span></div>{{/due_date}}</div><div style="text-align:center;margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;background:#111;color:#fff;text-decoration:none;padding:12px 24px;border-radius:8px;font-weight:600">Visa och betala fakturan</a></div><p style="margin:16px 0 0;font-size:12px;color:#6b7280;word-break:break-all">Eller kopiera länken: <br/>{{cta_url}}</p><hr style="border:none;border-top:1px solid #e6e8ec;margin:24px 0"/><p style="margin:0;font-size:12px;color:#9ca3af">Skickat av {{site_name}}</p></div></body></html>$tpl$, 'billing', $var$["invoice_number", "site_name", "items_rows", "subtotal", "tax", "total", "due_date", "cta_url", "custom_block"]$var$::jsonb, true
